 "content": "def transform(grid):
    # Reflect the color-4 figure vertically beneath its bounding box; discard the marker color.
    rows = [r[:] for r in grid]
    coords = [(i, j) for i, row in enumerate(rows) for j, v in enumerate(row) if v == 4]
    if not coords:
        return rows
    top, bottom = min(i for i, _ in coords), max(i for i, _ in coords)
    for offset in range(bottom - top + 1):
        src = bottom - offset
        dst = bottom + 1 + offset
        if dst >= len(rows):
            break
        for j in range(len(rows[0])):
            if rows[src][j] == 4:
                rows[dst][j] = 4
    for i in range(len(rows)):
        for j in range(len(rows[i])):
            if rows[i][j] == 6:
                rows[i][j] = 0
    return rows
