    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==4]
    marks=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==6]
    if not pts or not marks: return g
    mr0,mr1=min(r for r,c in marks),max(r for r,c in marks)
    # A T-shaped marker pointing upward requests a leftward horizontal reflection;
    # pointing downward requests a rightward reflection. Symmetric cross markers request vertical.
    widths=[sum(1 for r,c in marks if r==rr) for rr in range(mr0,mr1+1)]
    if max(widths)>1 and widths[-1]>widths[0]:
        edge=min(c for r,c in pts)
        for r,c in pts:
            cc=2*edge-1-c
            if 0<=cc<len(g[0]): g[r][cc]=4
