        edge=max(c for r,c in pts)
        for r,c in pts:
            cc=2*edge+1-c
            if 0<=cc<len(g[0]): g[r][cc]=4
    else:
        edge=max(r for r,c in pts)
        for r,c in pts:
            rr=2*edge+1-r
            if 0<=rr<len(g): g[rr][c]=4
    for r,c in marks: g[r][c]=0
    return g
